      "legend": "• 2500K - 3200K: Lilin & Lampu Pijar Rumah (Kuning/Jingga Hangat)<br>• 5500K - 5600K: Cahaya Matahari Siang Hari (Daylight Netral)<br>• 7000K - 9000K: Langit Berawan / Bayangan Mendung (Biru Dingin)"
