    "questionHtml": "Dalam operasional laboratorium percetakan offset di SMK jurusan DKV, kegiatan pencucian rol silinder tinta mesin cetak menghasilkan cairan sisa pelarut kimia dan residu tinta berbasis hidrokarbon. Berdasarkan regulasi K3LH dan lingkungan hidup (AMDAL), prosedur penanganan limbah cair berbahaya tersebut adalah...",
