    "subject": "rekayasa_desain",
    "mode": "latihan",
    "difficulty": "hard",
    "type": "mcq",
    "questionHtml": "Saat seorang desainer membuat logo vektor dengan bentuk rumit bertumpuk (compound path) di Illustrator, ia mendapati bahwa lubang di tengah lingkaran terkadang terisi warna atau tetap berlubang tergantung pengisian jalur kurva. Perbedaan mendasar antara aturan pengisian 'Non-Zero Winding Rule' dan 'Even-Odd Rule' dalam komputasi kurva vektor adalah...",
